"""Generate the CLI reference page from the `hab` cyclopts app.

Run after changing any CLI command, parameter, or help text:

    uv run python scripts/gen_cli_docs.py

`tests/test_cli_docs.py` fails if the committed page is out of date.
"""

import sys
from pathlib import Path

from cyclopts.docs.markdown import generate_markdown_docs

from habitat_mapper.main import app

OUTPUT_PATH = Path(__file__).resolve().parents[1] / "docs" / "reference" / "cli.md"

HEADER = """\
<!-- Generated by scripts/gen_cli_docs.py. Do not edit by hand. -->

# CLI Reference

Habitat-Mapper installs one command line tool, `hab`. It is available in the
environment that `habitat-mapper` is installed into. Every command also accepts
`--help` to print this information in your terminal.

"""


def render() -> str:
    """Render the CLI reference page as Markdown.

    Returns:
        The full page contents, ending in a single newline.
    """
    body = generate_markdown_docs(app, heading_level=2, generate_toc=False, no_root_title=True)
    return HEADER + body.strip() + "\n"


def main() -> None:
    """Write the CLI reference page to the docs directory."""
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT_PATH.write_text(render(), encoding="utf-8", newline="\n")
    sys.stdout.write(f"Wrote {OUTPUT_PATH}\n")


if __name__ == "__main__":
    main()
